using Microsoft.EntityFrameworkCore;

namespace PollViews.Data;

public static class AdminDatabaseInitializer
{
    public static Task EnsureTablesAsync(PollViewsDbContext db, CancellationToken cancellationToken = default) =>
        db.Database.ExecuteSqlRawAsync("""
            CREATE TABLE IF NOT EXISTS "AdminUsers" (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "Username" character varying(100) NOT NULL,
                "PasswordHash" character varying(500) NOT NULL,
                "IsActive" boolean NOT NULL,
                "MustChangePassword" boolean NOT NULL,
                "CreatedAt" timestamp with time zone NOT NULL
            );
            CREATE UNIQUE INDEX IF NOT EXISTS "IX_AdminUsers_Username" ON "AdminUsers" ("Username");
            CREATE TABLE IF NOT EXISTS "AdminReviews" (
                "SurveyResponseId" uuid PRIMARY KEY,
                "Status" integer NOT NULL,
                "Note" character varying(2000),
                "ReviewedByAdminUserId" integer NULL,
                "ReviewedAt" timestamp with time zone NULL,
                CONSTRAINT "FK_AdminReviews_SurveyResponses" FOREIGN KEY ("SurveyResponseId") REFERENCES "SurveyResponses" ("Id") ON DELETE CASCADE,
                CONSTRAINT "FK_AdminReviews_AdminUsers" FOREIGN KEY ("ReviewedByAdminUserId") REFERENCES "AdminUsers" ("Id") ON DELETE SET NULL
            );
            """, cancellationToken);
}
